AddressCheckClient.verify.source:
async verify(address: ResidencyDeclarationDto): Promise<AddressCheck> {
  const res = await fetch('https://address-check.example.com/v1/verify', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(address),
  });
  if (!res.ok) return { confirmed: false, reason: `address service answered ${res.status}` };
  const body = (await res.json()) as { match: 'exact' | 'partial' | 'none' };
  return body.match === 'exact' ? { confirmed: true } : { confirmed: false, reason: `address match: ${body.match}` };
}

ResidencyService.get.source:
async get(userId: string): Promise<ResidencyView> {
  const [latest, declarations] = await Promise.all([this.store.latest(userId), this.store.count(userId)]);
  return {
    userId,
    current: latest
      ? {
          countryOfResidence: latest.countryOfResidence, city: latest.city, postalCode: latest.postalCode,
          addressLine: latest.addressLine, status: latest.status, declaredAt: latest.declaredAt,
        }
      : null,
    declarations,
  };
}

ResidencyStore.latest.source:
async latest(userId: string): Promise<ResidencyDeclaration | null> {
  return this.rows.findOne({ where: { userId }, order: { declaredAt: 'DESC' } });
}

ResidencyStore.count.source:
async count(userId: string): Promise<number> {
  return this.rows.countBy({ userId });
}

ResidencyService.declare.source:
async declare(userId: string, dto: ResidencyDeclarationDto): Promise<ResidencyView> {
  const address = {
    countryOfResidence: dto.countryOfResidence.trim().toUpperCase(),
    city: dto.city.trim(),
    postalCode: dto.postalCode.replace(/\s+/g, '').toUpperCase(),
    addressLine: dto.addressLine.trim(),
  };
  if (this.policy.isRestricted(address.countryOfResidence)) {
    throw new UnprocessableEntityException({ message: `Residents of ${address.countryOfResidence} can't be onboarded` });
  }
  const check = await this.addressCheck.verify(address);
  const status = check.confirmed ? 'verified' : 'pending_review';
  await this.store.add(userId, address, status);
  this.events.emit('kyc.residency.declared', { userId, status, reason: check.reason });
  return this.get(userId);
}

ResidencyStore.add.source:
async add(userId: string, address: ResidencyDeclarationDto, status: ResidencyStatus): Promise<void> {
  await this.rows.insert({ userId, ...address, status, declaredAt: new Date().toISOString() });
}
